import { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import ReviewForm from '../components/ReviewForm';
import ReviewList from '../components/ReviewList';
import { getBook, getReviews, postReview, addToWishlist, removeFromWishlist } from '../api/backend';
import { useAuth } from '../auth/AuthContext';
import { useCart } from '../context/CartContext';

function BookDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [book, setBook] = useState(null);
  const [status, setStatus] = useState('loading');
  const [error, setError] = useState(null);
  const [reviews, setReviews] = useState([]);
  const [inWishlist, setInWishlist] = useState(false);
  const [wishlistBusy, setWishlistBusy] = useState(false);
  const [showSampleModal, setShowSampleModal] = useState(false);
  const [addedNotice, setAddedNotice] = useState(false);
  const [isOwned, setIsOwned] = useState(false);

  const { isLoggedIn, token, member } = useAuth();
  const { addToCart, isInCart } = useCart();

  useEffect(() => {
    if (!member?.id || !book?.id) {
      setIsOwned(false);
      return;
    }
    function checkOwnership() {
      try {
        const lib = JSON.parse(localStorage.getItem(`bookhub_library_${member.id}`) || '[]');
        setIsOwned(lib.some((b) => String(b.id) === String(book.id)));
      } catch {
        setIsOwned(false);
      }
    }
    checkOwnership();
    window.addEventListener('bookhub_library_updated', checkOwnership);
    return () => window.removeEventListener('bookhub_library_updated', checkOwnership);
  }, [member?.id, book?.id]);

  useEffect(() => {
    let ignore = false;
    async function load() {
      setStatus('loading');
      try {
        const b = await getBook(id);
        if (!ignore) { setBook(b); setStatus('success'); }
      } catch (err) {
        if (!ignore) { setError(err); setStatus('error'); }
      }
    }
    load();
    return () => { ignore = true; };
  }, [id]);

  useEffect(() => {
    let ignore = false;
    getReviews(id)
      .then(data => { if (!ignore) setReviews(data.items); })
      .catch(() => { if (!ignore) setReviews([]); });
    return () => { ignore = true; };
  }, [id]);

  async function handleReviewSubmit(text) {
    const saved = await postReview(id, text, token);
    setReviews([
      { ...saved, member: { id: member.id, displayName: member.displayName }, score: null },
      ...reviews,
    ]);
  }

  async function toggleWishlist() {
    if (!token) return;
    setWishlistBusy(true);
    try {
      if (inWishlist) {
        await removeFromWishlist(id, token);
        setInWishlist(false);
      } else {
        await addToWishlist(id, token);
        setInWishlist(true);
      }
    } catch {}
    setWishlistBusy(false);
  }

  if (status === 'loading') {
    return (
      <div className="mx-auto max-w-4xl animate-pulse px-4 py-10 md:px-6">
        <div className="flex flex-col gap-8 md:flex-row">
          <div className="aspect-[2/3] w-48 shrink-0 rounded-xl bg-slate-100" />
          <div className="flex-1 space-y-3">
            <div className="h-8 w-2/3 rounded bg-slate-100" />
            <div className="h-4 w-1/3 rounded bg-slate-100" />
            <div className="h-24 w-full rounded bg-slate-100" />
          </div>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className="mx-auto max-w-xl px-4 py-20 text-center">
        <p className="text-lg text-slate-700">ไม่พบหนังสือเล่มนี้ 😢</p>
        <p className="text-sm text-slate-400">{error.message}</p>
        <Link to="/books" className="mt-6 inline-block text-sm text-amber-600 hover:underline">กลับไปหน้าหนังสือทั้งหมด</Link>
      </div>
    );
  }

  const price = book.priceTHB ? `฿${Number(book.priceTHB).toLocaleString('th-TH')}` : 'ไม่ระบุราคา';

  return (
    <div className="mx-auto max-w-4xl px-4 py-10 md:px-6">
      <Link to="/books" className="text-sm text-slate-500 hover:text-amber-600">← กลับไปหน้าหนังสือทั้งหมด</Link>

      <div className="mt-4 flex flex-col gap-8 md:flex-row">
        {book.coverUrl ? (
          <img src={book.coverUrl} alt={`ปกหนังสือ ${book.title}`}
               className="w-48 shrink-0 self-start rounded-xl border border-slate-200" />
        ) : (
          <div className="grid aspect-[2/3] w-48 shrink-0 place-items-center rounded-xl bg-amber-50 text-5xl">📖</div>
        )}

        <div className="flex-1">
          <h1 className="text-2xl font-semibold text-slate-900 md:text-3xl">{book.title}</h1>
          <p className="mt-1 text-lg text-slate-600">{book.author}</p>
          <div className="mt-2 flex flex-wrap gap-2">
            {book.category && (
              <span className="rounded-full bg-amber-100 px-3 py-1 text-sm text-amber-700">{book.category}</span>
            )}
            {book.publicationYear && (
              <span className="rounded-full bg-slate-100 px-3 py-1 text-sm text-slate-600">ปี {book.publicationYear}</span>
            )}
            <span className="rounded-full bg-slate-100 px-3 py-1 text-sm text-slate-600">{price}</span>
            <span className="rounded-full bg-emerald-100 px-3 py-1 text-sm text-emerald-700">E-Book</span>
          </div>

          {book.isbn && <p className="mt-2 text-xs text-slate-400">ISBN: {book.isbn}</p>}
          {book.publisher && <p className="text-xs text-slate-400">สำนักพิมพ์: {book.publisher}</p>}

          {book.description && (
            <p className="mt-4 leading-relaxed text-slate-700">{book.description}</p>
          )}

          {/* แถบการสั่งซื้อและอ่านตัวอย่างสำหรับ E-Book */}
          <div className="mt-6 rounded-xl border border-amber-200 bg-amber-50/40 p-4">
            <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
              <div>
                <span className="text-xs text-slate-500">รูปแบบหนังสือ: </span>
                <span className="text-xs font-semibold text-emerald-700 bg-emerald-50 border border-emerald-200 rounded px-2 py-0.5">
                  ดิจิทัล E-Book (อ่านได้ทันที)
                </span>
              </div>
              <div className="text-right">
                <span className="text-2xl font-bold text-slate-900">{price}</span>
              </div>
            </div>

            {isOwned ? (
              <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-emerald-50 border border-emerald-200 p-4">
                <div className="flex items-center gap-2">
                  <span className="text-xl">✅</span>
                  <div>
                    <p className="font-bold text-emerald-900 text-sm">คุณเป็นเจ้าของ E-Book เล่มนี้แล้ว</p>
                    <p className="text-xs text-emerald-700">หนังสืออยู่ในชั้นหนังสือของคุณ สามารถเปิดอ่านได้ตลอดเวลา</p>
                  </div>
                </div>
                <Link
                  to="/me/library"
                  className="rounded-lg bg-emerald-600 px-4 py-2 text-xs font-bold text-white hover:bg-emerald-700 shadow-xs transition"
                >
                  📖 เปิดอ่านในชั้นหนังสือ
                </Link>
              </div>
            ) : (
              <div className="flex flex-wrap gap-2.5">
                {isLoggedIn ? (
                  <>
                    <button
                      onClick={() => {
                        addToCart(book);
                        setAddedNotice(true);
                        setTimeout(() => setAddedNotice(false), 2500);
                      }}
                      className={`flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold transition ${
                        isInCart(book.id)
                          ? 'border border-emerald-300 bg-emerald-50 text-emerald-700'
                          : 'border border-amber-400 bg-white text-amber-700 hover:bg-amber-50 shadow-sm'
                      }`}
                    >
                      {isInCart(book.id) ? '✓ อยู่ในตะกร้าแล้ว' : '🛒 เพิ่มเข้าตะกร้า'}
                    </button>

                    <button
                      onClick={() => {
                        addToCart(book);
                        navigate('/cart');
                      }}
                      className="flex items-center gap-2 rounded-lg bg-amber-500 px-5 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-amber-600 transition"
                    >
                      ⚡ สั่งซื้อ E-Book ทันที
                    </button>
                  </>
                ) : (
                  <Link
                    to="/login"
                    className="flex items-center gap-2 rounded-lg bg-amber-500 px-5 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-amber-600 transition"
                  >
                    🔒 เข้าสู่ระบบเพื่อสั่งซื้อ E-Book
                  </Link>
                )}

                <button
                  onClick={() => setShowSampleModal(true)}
                  className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-50 transition"
                >
                  📖 ทดลองอ่านตัวอย่าง
                </button>

                {isLoggedIn && (
                  <button
                    onClick={toggleWishlist}
                    disabled={wishlistBusy}
                    className={`flex items-center gap-2 rounded-lg border px-3 py-2.5 text-sm transition ${
                      inWishlist
                        ? 'border-amber-400 bg-amber-50 text-amber-700'
                        : 'border-slate-300 bg-white text-slate-600 hover:bg-amber-50'
                    }`}
                    title="รายการอยากอ่าน"
                  >
                    {inWishlist ? '❤️ อยากอ่านแล้ว' : '🤍 อยากอ่าน'}
                  </button>
                )}
              </div>
            )}

            {addedNotice && (
              <div className="mt-3 flex items-center justify-between rounded-lg bg-emerald-50 border border-emerald-200 px-3 py-2 text-xs text-emerald-800 animate-fadeIn">
                <span>✓ เพิ่มหนังสือเล่มนี้เข้าสู่ตะกร้าของคุณเรียบร้อยแล้ว</span>
                <Link to="/cart" className="font-semibold underline ml-2 hover:text-emerald-950">
                  ไปที่ตะกร้าสินค้า →
                </Link>
              </div>
            )}
          </div>

          {/* รีวิว */}
          <div className="mt-8">
            <h2 className="mb-3 text-lg font-semibold text-slate-900">รีวิวจากสมาชิก ({reviews.length})</h2>
            <ReviewList items={reviews} />
          </div>

          <div className="mt-6 rounded-xl border border-amber-100 bg-white p-5">
            {isLoggedIn ? (
              <ReviewForm key={book.id} bookTitle={book.title} onSubmit={handleReviewSubmit} />
            ) : (
              <p className="text-sm text-slate-500">
                <Link to="/login" className="text-amber-600 hover:underline">เข้าสู่ระบบ</Link> เพื่อเขียนรีวิว
              </p>
            )}
          </div>
        </div>
      </div>

      {/* Modal ทดลองอ่านตัวอย่าง */}
      {showSampleModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
          <div className="relative max-h-[85vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl">
            <div className="flex items-start justify-between border-b border-slate-100 pb-3">
              <div>
                <span className="rounded bg-amber-100 px-2 py-0.5 text-xs font-semibold text-amber-800">
                  ทดลองอ่าน E-Book
                </span>
                <h3 className="mt-1 text-xl font-bold text-slate-900">{book.title}</h3>
                <p className="text-xs text-slate-500">โดย {book.author}</p>
              </div>
              <button
                onClick={() => setShowSampleModal(false)}
                className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-700 text-lg"
              >
                ✕
              </button>
            </div>

            <div className="prose prose-slate my-4 max-w-none text-sm leading-relaxed text-slate-700">
              <h4 className="text-base font-semibold text-slate-800">บทนำ / เรื่องย่อ</h4>
              <p className="rounded-lg bg-slate-50 p-4 italic text-slate-600 border-l-4 border-amber-400">
                "{book.description || 'ไม่มีคำอธิบายเพิ่มเติม'}"
              </p>

              <h4 className="mt-4 text-base font-semibold text-slate-800">ตัวอย่างเนื้อหาบทที่ 1</h4>
              <p>
                ยินดีต้อนรับสู่หนังสือเล่มนี้ นี่คือส่วนหนึ่งของเนื้อหาตัวอย่างสำหรับการทดลองอ่านก่อนตัดสินใจสั่งซื้อ 
                ผู้อ่านสามารถสั่งซื้อฉบับเต็มเพื่อดาวน์โหลดไฟล์ (PDF / ePub) และอ่านต่อเนื่องได้อย่างราบรื่นบนทุกอุปกรณ์ 
                ทั้งสมาร์ตโฟน แท็บเล็ต หรือคอมพิวเตอร์ของคุณ
              </p>
              <div className="mt-4 rounded-xl bg-amber-50/50 p-3 text-xs text-slate-600 border border-amber-100 space-y-1">
                <p>• <strong>หมวดหมู่:</strong> {book.category || 'ทั่วไป'}</p>
                <p>• <strong>สำนักพิมพ์:</strong> {book.publisher || 'ไม่ระบุ'}</p>
                <p>• <strong>เลขมาตรฐานสากล (ISBN):</strong> {book.isbn || 'ไม่ระบุ'}</p>
                <p>• <strong>รูปแบบไฟล์:</strong> PDF, ePub (รองรับทุกอุปกรณ์)</p>
              </div>
            </div>

            <div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4">
              <span className="text-lg font-bold text-slate-900">{price}</span>
              <div className="flex gap-2">
                <button
                  onClick={() => setShowSampleModal(false)}
                  className="rounded-lg border border-slate-300 px-4 py-2 text-sm text-slate-600 hover:bg-slate-50"
                >
                  ปิดหน้าต่าง
                </button>
                {isLoggedIn ? (
                  <button
                    onClick={() => {
                      addToCart(book);
                      setShowSampleModal(false);
                      navigate('/cart');
                    }}
                    className="rounded-lg bg-amber-500 px-4 py-2 text-sm font-bold text-white hover:bg-amber-600 shadow-sm"
                  >
                    สั่งซื้อฉบับเต็มทันที
                  </button>
                ) : (
                  <Link
                    to="/login"
                    className="rounded-lg bg-amber-500 px-4 py-2 text-sm font-bold text-white hover:bg-amber-600 shadow-sm"
                  >
                    เข้าสู่ระบบเพื่อสั่งซื้อ
                  </Link>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default BookDetail;
